const r = await tools.exec_command({
  cmd: "sed -n '1,260p' .agents/skills/improve-codebase-architecture/SKILL.md",
  workdir: "/root/hevy-mcp",
  yield_time_ms: 10000,
  max_output_tokens: 30000
});
text(r.output);

const results = await Promise.all([
  tools.exec_command({
    cmd: "cat /root/.agents/skills/codebase-design/SKILL.md",
    workdir: "/root/hevy-mcp",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  }),
  tools.exec_command({
    cmd: "cat .agents/skills/improve-codebase-architecture/HTML-REPORT.md",
    workdir: "/root/hevy-mcp",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  })
]);
text(JSON.stringify({
  codebase_design: results[0].output,
  html_report: results[1].output
}, null, 2));

const p = await tools.update_plan({
  plan: [
    { step: "Inspect the authoritative checkout, domain glossary, ADRs, topology, tooling, and relevant prior decisions", status: "in_progress" },
    { step: "Run a bounded read-only Explorer scan for duplication, shallow modules, performance friction, and tooling complexity", status: "pending" },
    { step: "Reconcile findings against current code, tests, and documented decisions; rank concrete deepening candidates", status: "pending" },
    { step: "Create and open the temporary HTML architecture report, then hand off candidate selection", status: "pending" }
  ]
});
text(p);

const results = await Promise.all([
  tools.exec_command({
    cmd: "git status --short --branch && git rev-parse --show-toplevel && git rev-parse HEAD && git worktree list --porcelain",
    workdir: "/root/hevy-mcp",
    yield_time_ms: 10000,
    max_output_tokens: 12000
  }),
  tools.exec_command({
    cmd: "rg -n -C 3 \"Nx selective validation|architecture|deep module|validation-lanes|control-plane|script consolidation|repository/topology\" /root/.codex/memories/MEMORY.md",
    workdir: "/root/hevy-mcp",
    yield_time_ms: 10000,
    max_output_tokens: 20000
  }),
  tools.exec_command({
    cmd: "rg --files -g 'CONTEXT.md' -g 'docs/adr/**' -g 'repository/topology.json' -g 'package.json' -g 'CONTRIBUTING.md' -g 'docs/test-lanes.md' -g 'nx.json' -g 'repository/**' | sort",
    workdir: "/root/hevy-mcp",
    yield_time_ms: 10000,
    max_output_tokens: 20000
  })
]);
text(JSON.stringify({
  checkout: results[0].output,
  memory_hits: results[1].output,
  key_files: results[2].output
}, null, 2));

const r = await tools.exec_command({
  cmd: "git fetch origin main",
  workdir: "/root/hevy-mcp",
  yield_time_ms: 30000,
  max_output_tokens: 12000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "git status --short --branch && git rev-list --left-right --count HEAD...origin/main && git show-ref --verify --quiet refs/heads/refactor/architecture-improvement-scan-20260807; branch_status=$?; test -e /root/.codex/worktrees/hevy-architecture-improvement-scan-20260807; path_status=$?; printf 'branch_status=%s\\npath_status=%s\\n' \"$branch_status\" \"$path_status\"",
  workdir: "/root/hevy-mcp",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "git worktree add -b refactor/architecture-improvement-scan-20260807 /root/.codex/worktrees/hevy-architecture-improvement-scan-20260807 origin/main",
  workdir: "/root/hevy-mcp",
  yield_time_ms: 30000,
  max_output_tokens: 12000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "git status --short --branch && { test -f CONTEXT.md && printf 'CONTEXT.md present\\n' || printf 'CONTEXT.md absent\\n'; } && { test -d docs/adr && rg --files docs/adr || printf 'docs/adr absent\\n'; } && rg --files docs | sort",
  workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
text(r.output);

const results = await Promise.all([
  tools.exec_command({
    cmd: "wc -l CONTRIBUTING.md docs/architecture.md docs/testing-strategy.md docs/nx-dependency-cruiser-spike.md package.json nx.json repository/topology.json repository/validation-lanes.json repository/artifact-provenance.json repository/control-plane-baseline.json",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 12000
  }),
  tools.exec_command({
    cmd: "find packages scripts test tests -type f 2>/dev/null | sed 's#^./##' | sort | awk -F/ '{count[$1\"/\"$2]++} END {for (k in count) print count[k], k}' | sort -nr",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 12000
  }),
  tools.exec_command({
    cmd: "rg --files packages scripts test tests 2>/dev/null | xargs wc -l | sort -nr | head -60",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 12000
  })
]);
text(JSON.stringify({
  line_counts: results[0].output,
  file_counts: results[1].output,
  largest_files: results[2].output
}, null, 2));

const results = await Promise.all([
  tools.exec_command({
    cmd: "cat docs/architecture.md",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  }),
  tools.exec_command({
    cmd: "cat docs/nx-dependency-cruiser-spike.md",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 20000
  }),
  tools.exec_command({
    cmd: "cat package.json && cat nx.json && cat repository/topology.json",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 40000
  })
]);
text(JSON.stringify({
  architecture: results[0].output,
  nx_spike: results[1].output,
  config: results[2].output
}, null, 2));

const results = await Promise.all([
  tools.exec_command({
    cmd: "rg --files packages/core/src packages/operations/src packages/cli/src packages/node/src packages/worker/src packages/hevy-client/src -g '!packages/hevy-client/src/generated/**' | sort",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  }),
  tools.exec_command({
    cmd: "find . -name project.json -o -name 'tsdown.config.*' -o -name 'vitest*.config.*' | sort",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 12000
  }),
  tools.exec_command({
    cmd: "rg -n \"@hevy-mcp/operations|createHevyClient|HevyClient|withErrorHandling|registerTool|registerPrompt|registerResource\" packages/core/src packages/cli/src packages/node/src packages/worker/src -g '*.ts'",
    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  })
]);
text(JSON.stringify({
  source_files: results[0].output,
  project_files: results[1].output,
  usage_map: results[2].output
}, null, 2));

