    25	/**
    26	 * MCP tool response type aligned with MCP SDK CallToolResult while keeping
    27	 * content narrowed to text blocks for this server.
    28	 */
    29	export type McpToolResponse = Omit<CallToolResult, "content"> & {
    30		content: TextContent[];
    31		errorOutcome?: StructuredExecutionError;
    32	};
    33	
    34	type OutputShape = z.ZodRawShape;
    35	type OutputFor<TShape extends OutputShape> = z.output<z.ZodObject<TShape>>;
    36	
    37	export interface StructuredResponseContract<
    38		TData,
    39		TShape extends OutputShape,
    40	> extends ResponseContract<TData> {
    41		readonly outputSchema: TShape;
    42	}
    43	export interface ResponseContract<TData> {
    44		render(data: TData): McpToolResponse;
    45	}
    46	
    47	interface StructuredContractDefinition<TData, TShape extends OutputShape> {
    48		readonly outputSchema: TShape;
    49		readonly normalize: (data: TData) => unknown;
    50		readonly legacyJson: (output: OutputFor<TShape>) => unknown;
    51		readonly text?: (
    52			data: TData,
    53			output: OutputFor<TShape>,
    54		) => string | undefined;
    55		readonly additionalText?: (
    56			data: TData,
    57			output: OutputFor<TShape>,
    58		) => readonly string[];
    59		readonly telemetry?: (data: TData) => ToolResultTelemetry | undefined;
    60	}
    61	
    62	interface JsonContractPresentation {
    63		readonly json?: unknown;
    64		readonly text?: string;
    65		readonly additionalText?: readonly string[];
    66	}
    67	
    68	function jsonText(data: unknown): string {
    69		return JSON.stringify(data, null, 2) ?? "null";
    70	}
    71	
    72	function textContent(text: string): TextContent {
    73		return { type: "text", text };
    74	}
    75	
    76	export function defineStructuredResponseContract<
    77		const TShape extends OutputShape,
    78		TData,
    79	>(
    80		definition: StructuredContractDefinition<TData, TShape>,
    81	): StructuredResponseContract<TData, TShape> {
    82		return {
    83			outputSchema: definition.outputSchema,
    84			render(data) {
    85				const structuredContent = z
    86					.object(definition.outputSchema)
    87					.parse(definition.normalize(data));
    88				const text =
    89					definition.text?.(data, structuredContent) ??
    90					jsonText(definition.legacyJson(structuredContent));
    91				const additionalText =
    92					definition.additionalText?.(data, structuredContent) ?? [];
    93				const response: McpToolResponse = {
    94					content: [textContent(text), ...additionalText.map(textContent)],
    95					structuredContent,
    96				};
    97				attachResultTelemetry(response, definition.telemetry?.(data));
    98				return response;
    99			},
   100		};
   101	}
   102	
   103	export function defineJsonResponseContract<TData>(
   104		present: (data: TData) => JsonContractPresentation,
   105		telemetry?: (data: TData) => ToolResultTelemetry | undefined,
   106	): ResponseContract<TData> {
   107		return {
   108			render(data) {
   109				const presentation = present(data);
   110				const text = presentation.text ?? jsonText(presentation.json);
   111				const response: McpToolResponse = {
   112					content: [
   113						textContent(text),
   114						...(presentation.additionalText ?? []).map(textContent),
   115					],
   116				};
   117				attachResultTelemetry(response, telemetry?.(data));
   118				return response;
   119			},
   120		};
   121	}
