   264			event: "worker.oauth_response",
   265			...context,
   266			status,
   267		});
   268	}
   269	
   270	function executionHttpResponse(
   271		error: unknown,
   272		message: string,
   273		status: number,
   274		origin: string | null,
   275	): Response {
   276		return withCors(executionResponse(error, message, status), origin);
   277	}
   278	
   279	function resolveWorkerDependencies(
   280		dependencies: WorkerDependencies,
   281	): ResolvedWorkerDependencies {
   282		return {
   283			createValidationClient:
   284				dependencies.createValidationClient ?? createDefaultValidationClient,
   285			createRequestClient:
   286				dependencies.createRequestClient ?? createDefaultRequestClient,
   287			createServer: dependencies.createServer ?? createDefaultServer,
   288			createTransport: dependencies.createTransport ?? createDefaultTransport,
   289		};
   290	}
   291	
   292	async function validateHevyApiKey(
   293		apiKey: string,
   294		hevyApiBaseUrl: string,
   295		createValidationClient: ResolvedWorkerDependencies["createValidationClient"],
   296		options?: HevyRequestOptions,
   297	): Promise<HevyApiKeyValidation> {
   298		try {
   299			const validationDeadline = Math.min(
   300				options?.deadline ?? Number.POSITIVE_INFINITY,
   301				Date.now() + WORKER_VALIDATION_TIMEOUT_MS,
   302			);
   303			await createValidationClient(apiKey, hevyApiBaseUrl).getUserInfo({
   304				...options,
   305				deadline: validationDeadline,
   306			});
   307			return "valid";
   308		} catch (error) {
   309			if (options?.signal?.aborted) throw error;
   310			if (isHevyHttpError(error) && error.outcome === "deadline_exceeded") {
   311				throw error;
   312			}
   313			if (
   314				isHevyHttpError(error) &&
   315				(error.status === 401 || error.status === 403)
   316			) {
   317				return "invalid";
   318			}
   319			throw error;
   320		}
   321	}
   322	
   323	async function serveMcpRequest(
   324		request: Request,
   325		apiKey: string,
   326		hevyApiBaseUrl: string,
   327		dependencies: ResolvedWorkerDependencies,
   328		deadline: number,
   329	): Promise<Response> {
   330		try {
   331			const server = dependencies.createServer(
   332				({ onLog }) =>
   333					dependencies.createRequestClient(apiKey, hevyApiBaseUrl, onLog),
   334				request.signal,
   335				deadline,
   336			);
   337			const transport = dependencies.createTransport();
   338			transport.onerror = (error) => {
   339				logWorkerFailure("streamable-http-transport", error);
   340			};
   341			await server.connect(transport);
   342			return await transport.handleRequest(request);
   343		} catch (error) {
   344			logWorkerFailure("mcp-request-processing", error);
   345			return executionHttpResponse(
   346				error,
   347				"Unable to process MCP request",
   348				500,
   349				null,
   350			);
   351		}
   352	}
   353	
   354	export function createWorkerHandler(dependencies: WorkerDependencies = {}) {
   355		const resolved = resolveWorkerDependencies(dependencies);
   356	
   357		return async function handleRequest(
   358			request: Request,
   359			env: WorkerEnv,
   360		): Promise<Response> {
   360		): Promise<Response> {
   361			const url = new URL(request.url);
   362			if (url.pathname !== MCP_PATH)
   363				return new Response("Not found", { status: 404 });
   364	
   365			const originResult = validateOrigin(request, env);
   366			if (originResult instanceof Response) return originResult;
   367			const origin = originResult;
   368			let hevyApiBaseUrl: string;
   369			try {
   370				hevyApiBaseUrl = resolveHevyApiBaseUrl(env.HEVY_API_BASE_URL);
   371			} catch {
   372				return response("Worker configuration error", 500, origin);
   373			}
   374	
   375			if (request.method === "OPTIONS") {
   376				const headers = origin ? corsHeaders(origin) : new Headers();
   377				headers.set("Access-Control-Allow-Methods", CORS_ALLOWED_METHODS);
   378				headers.set("Access-Control-Allow-Headers", CORS_ALLOWED_HEADERS);
   379				headers.set("Access-Control-Max-Age", "86400");
   380				return new Response(null, { status: 204, headers });
   381			}
   382	
   383			if (request.method !== "POST") {
   384				return response("Method not allowed", 405, origin, {
   385					Allow: CORS_ALLOWED_METHODS,
   386				});
   387			}
   388	
   389			const apiKey = parseBearerApiKey(request.headers.get("authorization"));
   390			if (!apiKey) {
   391				return response("Unauthorized", 401, origin, {
   392					"WWW-Authenticate": "Bearer",
   393				});
   394			}
   395	
   396			const deadline = Date.now() + WORKER_INVOCATION_TIMEOUT_MS;
   397			let validation: HevyApiKeyValidation;
   398			try {
   399				validation = await validateHevyApiKey(
   400					apiKey,
   401					hevyApiBaseUrl,
   402					resolved.createValidationClient,
   403					{
   404						signal: request.signal,
   405						deadline,
   406					},
   407				);
   408			} catch (error) {
   409				return executionHttpResponse(
   410					error,
   411					"Unable to validate the Hevy API key",
   412					502,
   413					origin,
   414				);
   415			}
   416			if (validation === "invalid") {
   417				return response("Unauthorized", 401, origin, {
   418					"WWW-Authenticate": "Bearer",
   419				});
   420			}
   421	
   422			return withCors(
   423				await serveMcpRequest(
   424					request,
   425					apiKey,
   426					hevyApiBaseUrl,
   427					resolved,
   428					deadline,
   429				),
   430				origin,
   431			);
   432		};
   433	}
   434	
   435	function createWorkerOAuthProvider(
   436		resolved: ResolvedWorkerDependencies,
   437	): HevyOAuthWorker<WorkerEnv> {
   438		return createHevyOAuthProvider<WorkerEnv>({
   439			validateApiKey: async (apiKey, env, signal, deadline) => {
   440				let hevyApiBaseUrl: string;
   441				try {
   442					hevyApiBaseUrl = resolveHevyApiBaseUrl(env.HEVY_API_BASE_URL);
   443				} catch {
   444					return "config-error";
   445				}
   446				return validateHevyApiKey(
   447					apiKey,
   448					hevyApiBaseUrl,
   449					resolved.createValidationClient,
   450					{
   451						signal,
   452						deadline: deadline ?? Date.now() + WORKER_INVOCATION_TIMEOUT_MS,
   453					},
   454				);
   455			},
   456			serveMcp: async (request, env, apiKey, deadline) => {
   457				let hevyApiBaseUrl: string;
   458				try {
   459					hevyApiBaseUrl = resolveHevyApiBaseUrl(env.HEVY_API_BASE_URL);
   460				} catch {
   461					return new Response("Worker configuration error", { status: 500 });
   462				}
   463				return serveMcpRequest(
   464					request,
   465					apiKey,
   466					hevyApiBaseUrl,
   467					resolved,
   468					deadline ?? Date.now() + WORKER_INVOCATION_TIMEOUT_MS,
   469				);
   470			},
   471		});
   472	}
   473	
   474	/**
   475	 * Compose the legacy direct-API-key handler with the optional OAuth layer.
   476	 *
   477	 * Without an `OAUTH_KV` binding every request takes the legacy path, so
   478	 * existing deployments are unaffected. With the binding, `/mcp` requests
   479	 * whose bearer value looks like an OAuth access token (and unauthenticated
   480	 * ones, so clients receive the RFC 9728 discovery challenge) go through the
   481	 * OAuth provider, while raw Hevy API keys keep using the legacy path.
   482	 */
   483	export function createWorkerFetchHandler(
   484		dependencies: WorkerDependencies = {},
   485	) {
   486		const resolved = resolveWorkerDependencies(dependencies);
   487		const legacyHandler = createWorkerHandler(dependencies);
   488		const oauthProvider = createWorkerOAuthProvider(resolved);
   489	
   490		return async function handleWorkerFetch(
   491			request: Request,
   492			env: WorkerEnv,
   493			ctx?: object,
   494		): Promise<Response> {
   495			const logContext = createRequestLogContext(request, env);
   496			const startedAt = Date.now();
   497			let responseStatus: number | null = null;
   498			try {
   499				if (!isOAuthEnabled(env)) {
   500					if (env.OAUTH_KV != null) {
   501						logWorkerFailure(
   502							"oauth-kv-misconfigured",
   503							new TypeError(
   504								"OAUTH_KV binding is not a KV namespace; OAuth stays disabled",
   505							),
   506							logContext,
   507						);
   508					}
   509					const legacyResponse = await legacyHandler(request, env);
   510					responseStatus = legacyResponse.status;
   511					return legacyResponse;
   512				}
   513	
   514				const originResult = validateOrigin(request, env);
   515				if (originResult instanceof Response) {
   516					responseStatus = originResult.status;
   517					return originResult;
   518				}
   519				const origin = originResult;
   520				const url = new URL(request.url);
   521				if (url.pathname === MCP_PATH) {
   522					if (request.method === "OPTIONS") {
   523						const legacyResponse = await legacyHandler(request, env);
   524						responseStatus = legacyResponse.status;
   525						return legacyResponse;
   526					}
   527					const bearer = parseBearerApiKey(request.headers.get("authorization"));
   528					if (bearer && !hasOAuthAccessTokenShape(bearer)) {
   529						const legacyResponse = await legacyHandler(request, env);
   530						responseStatus = legacyResponse.status;
   531						return legacyResponse;
   532					}
   533					const oauthResponse = await oauthProvider.fetch(
   534						request,
   535						env,
   536						ctx ?? {},
   537					);
   538					responseStatus = oauthResponse.status;
   539					logOAuthResponse(logContext, responseStatus);
   540					return withCors(oauthResponse, origin);
   541				}
   542				const oauthResponse = await oauthProvider.fetch(request, env, ctx ?? {});
   543				responseStatus = oauthResponse.status;
   544				logOAuthResponse(logContext, responseStatus);
   545				return withCors(oauthResponse, origin);
   546			} catch (error) {
   547				logWorkerFailure("request", error, logContext);
   548				throw error;
   549			} finally {
   550				console.log({
   551					event: "worker.request",
   552					...logContext,
   553					status: responseStatus,
   554					durationMs: Date.now() - startedAt,
   555				});
   556			}
   557		};
   558	}
   559	
   560	const handleWorkerFetch = createWorkerFetchHandler();
   561	
   562	export default {
   563		fetch(request: Request, env: WorkerEnv, ctx?: object): Promise<Response> {
   564			return handleWorkerFetch(request, env, ctx);
   565		},
   566	};
