  1	import { createExecutionErrorProjection } from "@hevy-mcp/core";
  2	
  3	export interface ExecutionOutcome {
  4		readonly execution: ReturnType<typeof createExecutionErrorProjection>;
  5		readonly status: number;
  6	}
  7	
  8	/** Compute one bounded projection and transport status for a failure. */
  9	export function executionOutcome(
 10		error: unknown,
 11		fallback: number,
 12	): ExecutionOutcome {
 13		const execution = createExecutionErrorProjection(error);
 14		const status =
 15			execution.outcome === "deadline_exceeded"
 16				? 504
 17				: execution.outcome === "cancelled"
 18					? 499
 19					: fallback;
 20		return { execution, status };
 21	}
 22	
 23	/**
 24	 * Render one privacy-safe execution projection for Worker HTTP adapters.
 25	 * Callers choose the transport-specific status and message; the outcome
 26	 * fields always come from the shared core/client taxonomy.
 27	 */
 28	export function executionResponse(
 29		error: unknown,
 30		message: string,
 31		statusOrOutcome: number | ExecutionOutcome,
 32	): Response {
 33		const outcome =
 34			typeof statusOrOutcome === "number"
 35				? executionOutcome(error, statusOrOutcome)
 36				: statusOrOutcome;
 37		return new Response(
 38			JSON.stringify({ error: { message, ...outcome.execution } }),
 39			{
 40				status: outcome.status,
 41				headers: { "Content-Type": "application/json" },
 42			},
 43		);
 44	}
 45	
 46	export function executionStatus(error: unknown, fallback: number): number {
 47		return executionOutcome(error, fallback).status;
 48	}
