   103	export function createExecutionSignal(control: HevyExecutionControl): {
   104		signal: AbortSignal;
   105		abort: (reason?: unknown) => void;
   106		cleanup: () => void;
   107		deadlineTriggered: () => boolean;
   108	} {
   109		const controller = new AbortController();
   110		let deadlineTriggered = false;
   111		const abortFromCaller = () => {
   112			if (!controller.signal.aborted) controller.abort(control.signal?.reason);
   113		};
   114		if (control.signal?.aborted) abortFromCaller();
   115		else
   116			control.signal?.addEventListener("abort", abortFromCaller, { once: true });
   117		let timer: ReturnType<typeof setTimeout> | undefined;
   118		if (control.deadline !== undefined) {
   119			const delay = Math.max(0, control.deadline - Date.now());
   120			timer = setTimeout(() => {
   121				deadlineTriggered = true;
   122				if (!controller.signal.aborted) {
   123					controller.abort(
   124						new DOMException("Operation deadline exceeded", "TimeoutError"),
   125					);
   126				}
   127			}, delay);
   128		}
   129		return {
   130			signal: controller.signal,
   131			abort: (reason?: unknown) => {
   132				if (!controller.signal.aborted) controller.abort(reason);
   133			},
   134			cleanup: () => {
   135				if (timer !== undefined) clearTimeout(timer);
   136				control.signal?.removeEventListener("abort", abortFromCaller);
   137			},
   138			deadlineTriggered: () => deadlineTriggered,
   139		};
   140	}
