    10	export interface WorkoutsListInput {
    11		readonly page: number;
    12		readonly pageSize: number;
    13	}
    14	
    15	export interface WorkoutsListOutput {
    16		readonly items: Workout[];
    17		readonly page: number;
    18		readonly pageCount?: number;
    19		readonly expected404Outcome?: "end_of_list";
    20	}
    21	
    22	export type WorkoutsListAdapter = Pick<HevyClient, "getWorkouts">;
    23	
    24	export interface WorkoutsListDescriptor {
    25		readonly id: "workouts.list";
    26		readonly safety: Extract<HevyOperationSafety, "read">;
    27	}
    28	
    29	export const workoutsListDescriptor: WorkoutsListDescriptor = {
    30		id: "workouts.list",
    31		safety: "read",
    32	};
    33	
    34	export interface WorkoutsListOperation {
    35		readonly descriptor: WorkoutsListDescriptor;
    36		execute(
    37			input: WorkoutsListInput,
    38			options?: HevyExecutionOptions,
    39		): Promise<WorkoutsListOutput>;
    40	}
    41	
    42	function isExpectedEndOfList(error: unknown, page: number): boolean {
    43		return (
    44			page > 1 &&
    45			isHevyHttpError(error) &&
    46			error.status === 404 &&
    47			error.method.toUpperCase() === "GET" &&
    48			error.endpoint === "/v1/workouts"
    49		);
    50	}
    51	
    52	function normalizeWorkoutsPage(
    53		response: GetV1Workouts200,
    54		input: WorkoutsListInput,
    55	): WorkoutsListOutput {
    56		if (response.page !== undefined && response.page !== input.page) {
    57			throw new Error(
    58				`Workouts page mismatch: requested page ${input.page} but received page ${response.page}`,
    59			);
    60		}
    61		return {
    62			items: response.workouts ?? [],
    63			page: response.page ?? input.page,
    64			pageCount: response.page_count,
    65		};
    66	}
    67	
    68	export function createWorkoutsListOperation(
    69		adapter: WorkoutsListAdapter,
    70	): WorkoutsListOperation {
    71		return {
    72			descriptor: workoutsListDescriptor,
    73			async execute(input, options) {
    74				try {
    75					const params = { page: input.page, pageSize: input.pageSize };
    76					const response =
    77						options === undefined
    78							? await adapter.getWorkouts(params)
    79							: await adapter.getWorkouts(params, options);
    80					return normalizeWorkoutsPage(response, input);
    81				} catch (error) {
    82					if (isExpectedEndOfList(error, input.page)) {
    83						return {
    84							items: [],
    85							page: input.page,
    86							pageCount: undefined,
    87							expected404Outcome: "end_of_list",
    88						};
    89					}
    90					throw error;
    91				}
    92			},
    93		};
    94	}
    95	
    96	export function isWorkoutsListEndOfList(
    97		error: unknown,
    98		page: number,
    99	): error is HevyHttpError {
   100		return isExpectedEndOfList(error, page);
   101	}

