   414	export async function runServer(): Promise<void> {
   415		const args = process.argv.slice(2);
   416		const cliAction = getCliAction(args);
   417		if (cliAction === "version") {
   418			console.error(`${name} v${version}`);
   419			return;
   420		}
   421		if (cliAction === "help") {
   422			console.log(HELP_TEXT);
   423			return;
   424		}
   425	
   426		const options = parseNodeCliOptions(args);
   427		if (options.transport === "stdio") {
   428			await runStdioServer();
   429			return;
   430		}
   431		const cleanupProcessExceptionTracking = installProcessExceptionTracking();
   432		const lifecycleController = new AbortController();
   433	
   434		await tracer.startActiveSpan(
   435			"mcp.server.run",
   436			{
   437				attributes: {
   438					"mcp.span.category": "startup",
   439					"mcp.transport": "http",
   440				},
   441			},
   442			async (span) => {
   443				let listening = false;
   444				serverStartups.add(1, { version });
   445				try {
   446					const cfg = parseConfig(process.env);
   447					assertApiKey(cfg.apiKey);
   448					await validateApiKey(cfg.apiKey, lifecycleController.signal);
   449					const handle = await startStreamableHttpServer(
   450						options,
   451						cfg.apiKey,
   452						(params) =>
