    25	 * Callers choose the transport-specific status and message; the outcome
    26	 * fields always come from the shared core/client taxonomy.
    27	 */
    28	export function executionResponse(
    29		error: unknown,
    30		message: string,
    31		statusOrOutcome: number | ExecutionOutcome,
    32	): Response {
    33		const outcome =
    34			typeof statusOrOutcome === "number"
    35				? executionOutcome(error, statusOrOutcome)
    36				: statusOrOutcome;
    37		return new Response(
    38			JSON.stringify({ error: { message, ...outcome.execution } }),
    39			{
