   263	export function deserializeMessageWithObservability(
   264		line: string,
   265		chunkSnapshot: StdioChunkSnapshot,
   266	): JSONRPCMessage {
   267		const lineHadLeadingBom = line.startsWith(UTF8_BOM);
   268		const normalizedLine = lineHadLeadingBom ? line.slice(1) : line;
   269		const lineByteLength = Buffer.byteLength(line);
   270		const sessionId = getCurrentMcpSessionId();
   271		return tracer.startActiveSpan(
   272			"mcp.stdio.deserialize",
   273			{
   274				attributes: {
   275					"mcp.span.category": "protocol",
   276					"mcp.transport": "stdio",
   277					"mcp.stdio.parse.line.char_length": line.length,
   278					"mcp.stdio.parse.line.byte_length": lineByteLength,
   279					"mcp.stdio.parse.line.had_leading_bom": lineHadLeadingBom,
   280					"mcp.stdio.parse.line.bom_stripped": lineHadLeadingBom,
   281					"mcp.stdio.parse.chunk.last_byte_length":
   282						chunkSnapshot.lastChunkByteLength,
   283					"mcp.stdio.parse.chunk.last_had_utf8_bom":
   284						chunkSnapshot.lastChunkStartsWithUtf8Bom,
   285					...(sessionId ? { "mcp.session.id": sessionId } : {}),
   286				},
   287			},
   288			(span) => {
   289				try {
   290					const message = deserializeMessage(normalizedLine);
   291					span.setStatus({ code: SpanStatusCode.OK });
   292					if (message && typeof message === "object" && "method" in message) {
   293						const method = message.method;
   294						if (typeof method === "string" && SAFE_MCP_METHODS[method] === true) {
   295							span.setAttribute("mcp.method", method);
   296						}
   297						if (method === "initialize") {
   298							const client = recordMcpSessionStart(message);
   299							const sessionId = getCurrentMcpSessionId();
   300							if (sessionId) {
   301								span.setAttribute("mcp.session.id", sessionId);
   302							}
   303							span.setAttribute("mcp.client.name", client.name);
   304							span.setAttribute("mcp.client.version", client.version);
   305							span.setAttribute("mcp.protocol.version", client.protocolVersion);
   306						}
   307					}
   308					return message;
   309				} catch (error) {
   310					const diagnostic = createSafeErrorDiagnostic(error);
   311					const failurePosition = parseFailurePosition(error);
   312					const failureLocation = getFailureLocation(
   313						failurePosition,
   314						lineHadLeadingBom,
   315					);
   316	
   317					span.setStatus({ code: SpanStatusCode.ERROR });
   318					span.addEvent("mcp.stdio.parse.failure", {
   319						"error.category": diagnostic.category,
   320					});
   321					span.setAttribute("mcp.stdio.parse.failure.location", failureLocation);
   322					if (failurePosition !== null) {
   323						span.setAttribute(
   324							"mcp.stdio.parse.failure.position",
   325							failurePosition,
   326						);
   327					}
   328	
   329					stdioParseErrors.add(1, { failure_location: failureLocation });
   330	
   331					reportStdinParseFailure(
   332						error,
   333						line,
   334						lineByteLength,
   335						failureLocation,
   336						failurePosition,
   337					);
   338	
   339					throw error;
   340				} finally {
   341					span.end();
   342				}
   343			},
   344		);
   345	}
   346	
   347	export function createInstrumentedStdioTransport<
   348		T extends StdioServerTransport,
   349	>(transport: T): T {
   350		const privateAdapter = createSdkPrivateStdioAdapter(transport);
   351		let lastChunkSnapshot: StdioChunkSnapshot = {
   352			lastChunkByteLength: 0,
   353			lastChunkStartsWithUtf8Bom: false,
   354		};
   355	
   356		privateAdapter.wrapOnData((chunk) => {
   357			lastChunkSnapshot = {
   358				lastChunkByteLength: chunk.byteLength,
   359				lastChunkStartsWithUtf8Bom: hasUtf8BomPrefix(chunk),
   360			};
   361		});
   362	
   363		const didInstallReadMessageHook = privateAdapter.installReadMessageHook(
   364			(line) => deserializeMessageWithObservability(line, lastChunkSnapshot),
   365		);
   366		if (!didInstallReadMessageHook) {
   367			return transport;
   368		}
   369	
   370		return transport;
   371	}

