   301	function parseSseEvents(payload: string): SseEvent[] {
   302		const events: SseEvent[] = [];
   303		let data: string[] = [];
   304		let event = "message";
   305		const dispatch = () => {
   306			if (data.length === 0) return;
   307			events.push({ data: data.join("\n"), event });
