   309			event = "message";
   310		};
   311	
   312		for (const line of payload.replaceAll("\r\n", "\n").split("\n")) {
   313			if (line === "") {
   314				dispatch();
   315				continue;
   316			}
   317			if (line.startsWith(":")) continue;
   318			const separator = line.indexOf(":");
   319			const field = separator === -1 ? line : line.slice(0, separator);
   320			const rawValue = separator === -1 ? "" : line.slice(separator + 1);
   321			const value = rawValue.startsWith(" ") ? rawValue.slice(1) : rawValue;
   322			if (field === "data") data.push(value);
   323			else if (field === "event") event = value;
   324		}
   325		dispatch();
   326		return events;
   327	}
