/// <reference types="node" />
import { readFileSync } from "node:fs";
import { codecovRollupPlugin } from "@codecov/rollup-plugin";
import { sentryRollupPlugin } from "@sentry/rollup-plugin";
import { defineConfig } from "tsdown";

interface PackageJsonMeta {
	name?: unknown;
	version?: unknown;
}

const pkgJsonRaw = readFileSync(
	new URL("./package.json", import.meta.url),
	"utf-8",
);
let parsed: PackageJsonMeta;
try {
	parsed = JSON.parse(pkgJsonRaw) as PackageJsonMeta;
} catch (error) {
	throw new Error(`Failed to parse package.json: ${(error as Error).message}`);
}

const { name, version } = parsed;
const isStandaloneBuild = process.env.HEVY_MCP_BUILD_MODE === "standalone";
const isReleaseBuild = process.env.HEVY_MCP_RELEASE === "true";
const codecovToken = process.env.CODECOV_TOKEN?.trim() || undefined;
const enableCodecovBundleAnalysis =
	!isStandaloneBuild && codecovToken !== undefined;

if (process.env.HEVY_MCP_RELEASE === "true") {
	const missing: string[] = [];
	if (!process.env.OTEL_COLLECTOR_TOKEN) missing.push("OTEL_COLLECTOR_TOKEN");
	if (!process.env.SENTRY_ORG) missing.push("SENTRY_ORG");
	if (!process.env.SENTRY_PROJECT) missing.push("SENTRY_PROJECT");
	if (!process.env.SENTRY_AUTH_TOKEN) missing.push("SENTRY_AUTH_TOKEN");

	if (missing.length > 0) {
		throw new Error(
			`Release build failed: Missing required environment variables: ${missing.join(
				", ",
			)}`,
		);
	}
}

if (
	typeof name !== "string" ||
	typeof version !== "string" ||
	!name ||
	!version
) {
	throw new Error(
		`package.json must provide non-empty string 'name' and 'version'. Got name=${String(
			name,
		)}, version=${String(version)}`,
	);
}
export default defineConfig({
	entry: isStandaloneBuild ? ["src/cli.ts"] : ["src/index.ts", "src/cli.ts"],
	format: ["esm"],
	platform: isStandaloneBuild ? "node" : undefined,
	target: isStandaloneBuild ? "node24" : "esnext",
	define: {
		__HEVY_MCP_BUILD__: "true",
		__HEVY_MCP_NAME__: JSON.stringify(name),
		__HEVY_MCP_VERSION__: JSON.stringify(version),
		__OTEL_COLLECTOR_TOKEN__: JSON.stringify(
			process.env.OTEL_COLLECTOR_TOKEN ?? "",
		),
	},
	// Release builds upload source maps to Sentry and remove them after upload;
	// normal and published builds intentionally omit them.
	sourcemap: isReleaseBuild,
	clean: true,
	dts: !isStandaloneBuild,
	deps: isStandaloneBuild
		? {
				alwaysBundle: [/.*/],
				onlyBundle: false,
			}
		: {
				// Keep the private workspace graph inside the public artifact. Only
				// Node's declared runtime dependencies remain external.
				alwaysBundle: [
					"@hevy-mcp/core",
					"@hevy-mcp/hevy-client",
					"@hevy-mcp/operations",
				],
			},
	banner: {
		js: "#!/usr/bin/env node\n// Generated with tsdown\n// https://tsdown.dev",
	},
	outDir: "dist",
	outputOptions: isStandaloneBuild
		? {
				codeSplitting: false,
				entryFileNames: "standalone.mjs",
			}
		: undefined,
	inputOptions: {
		onLog(level, log, defaultHandler) {
			if (
				typeof log === "object" &&
				log !== null &&
				"code" in log &&
				log.code === "SOURCEMAP_BROKEN"
			) {
				return;
			}
			defaultHandler(level, log);
		},
	},
	plugins: [
		sentryRollupPlugin({
			org: process.env.SENTRY_ORG,
			project: process.env.SENTRY_PROJECT,
			authToken: process.env.SENTRY_AUTH_TOKEN,
			telemetry: false,
			sourcemaps: {
				assets: ["./dist/**/*.mjs", "./dist/**/*.map"],
				...(isReleaseBuild
					? { filesToDeleteAfterUpload: ["./dist/**/*.map"] }
					: {}),
			},
			release: {
				name: `${name}@${version}`,
			},
		}),
		...(enableCodecovBundleAnalysis
			? codecovRollupPlugin({
					enableBundleAnalysis: true,
					bundleName: "hevy-mcp",
					uploadToken: codecovToken,
				})
			: []),
	],
});
import { performance } from "node:perf_hooks";
import { expect, it } from "vitest";
import {
	callPerformanceTool,
	createPerformanceHarness,
	measuredDuration,
	observeServerRss,
	type PerformanceHarness,
} from "./harness.js";
import {
	createPerformanceReport,
	performanceReportSchema,
	type PerformanceScenario,
	writePerformanceReport,
} from "./report.js";
import {
	createScenarioState,
	finalizeScenario,
	recordFailure,
	recordFixtureResult,
	type ScenarioState,
} from "./scenario.js";

const STARTUP_ITERATIONS = 10;
const TOOLS_LIST_ITERATIONS = 20;
const MOCKED_READ_ITERATIONS = 20;
const CONCURRENT_CALLS = 20;
const SEQUENTIAL_CALLS = 100;

async function closeHarness(
	state: ScenarioState,
	harness: PerformanceHarness,
	iteration: number,
) {
	state.serverMemory.push(
		observeServerRss(harness.pid, iteration, "scenario-complete"),
	);
	try {
		recordFixtureResult(state, iteration, await harness.close());
	} catch (error) {
		recordFailure(state, iteration, "cleanup", error);
	}
}

async function runStartupScenario() {
	const state = createScenarioState(
		"startup-initialization",
		STARTUP_ITERATIONS,
		{
			description: "Startup plus MCP initialize p95 below 2 seconds",
			p95Milliseconds: 2_000,
			informationalOnly: true,
		},
	);
	const scenarioStartedAt = performance.now();

	for (let iteration = 1; iteration <= STARTUP_ITERATIONS; iteration += 1) {
		const startedAt = performance.now();
		let harness: PerformanceHarness | undefined;
		try {
			harness = await createPerformanceHarness("startup");
			state.durations.push(measuredDuration(startedAt));
			state.completedIterations += 1;
			state.serverMemory.push(
				observeServerRss(harness.pid, iteration, "initialized"),
			);
		} catch (error) {
			state.durations.push(measuredDuration(startedAt));
			recordFailure(state, iteration, "setup", error);
		}
		if (harness) await closeHarness(state, harness, iteration);
	}

	return finalizeScenario(state, measuredDuration(scenarioStartedAt));
}

async function runSingleProcessScenario(
	state: ScenarioState,
	mode:
		| "tools-list"
		| "representative-read"
		| "concurrent-reads"
		| "sequential-reads",
	operation: (harness: PerformanceHarness) => Promise<void>,
) {
	const scenarioStartedAt = performance.now();
	let harness: PerformanceHarness | undefined;
	try {
		harness = await createPerformanceHarness(mode);
	} catch (error) {
		state.durations.push(measuredDuration(scenarioStartedAt));
		recordFailure(state, 1, "setup", error);
	}

	if (harness) {
		try {
			state.serverMemory.push(observeServerRss(harness.pid, 1, "initialized"));
			await operation(harness);
		} catch (error) {
			if (state.durations.length === 0) {
				state.durations.push(measuredDuration(scenarioStartedAt));
			}
			recordFailure(state, 1, "operation", error);
		} finally {
			await closeHarness(
				state,
				harness,
				Math.max(state.completedIterations, 1),
			);
		}
	}
	return finalizeScenario(state, measuredDuration(scenarioStartedAt));
}

async function runToolsListScenario() {
